export class DynamicDropdownController{constructor(){this.#t()}#t(){const t=$("select[data-select2-id]");$(t).on("change",t=>{this.#o($(t.target))})}#o(t){const o=$.escapeSelector(t.prop("name"));const e=$(`[data-glpi-parent-dropdown="${CSS.escape(o)}"]`);const a=t.val();e.each((t,o)=>{const e=$(o).data("glpi-parent-dropdown-condition");$(o).toggleClass("d-none",e!==a)})}}